		'id'       => 'menu-novaposhta',
		'icon'     => 'fa-truck',
		'name'     => 'Нова Пошта',
		'href'     => '',
		'children' => array(
			array(
				'name'     => 'Налаштування',
				'href'     => $this->url->link('extension/shipping/novaposhta', 'user_token=' . $this->session->data['user_token'], true),
				'children' => array()
			),
			array(
				'name'     => 'Диспетчер ЕН',
				'href'     => $this->url->link('extension/shipping/novaposhta/dispatch', 'user_token=' . $this->session->data['user_token'], true),
				'children' => array()
			)
		)
	);
}
